export function installJournal({pause,rewards,lounges,residents,villages,builders,library,eldergrove,school,founder}){
 const $=s=>document.querySelector(s),dialog=document.createElement('dialog');dialog.id='keepsakeJournal';dialog.setAttribute('aria-labelledby','journalTitle');
 const title=document.createElement('h2');title.id='journalTitle';title.textContent='Your keepsake journal';const summary=document.createElement('p');summary.id='journalSummary';const filters=document.createElement('div');filters.id='journalFilters';const body=document.createElement('div');body.id='journalItems';const close=document.createElement('button');close.id='journalClose';close.textContent='Close';close.onclick=()=>dialog.close();const safariNotes=document.createElement('details');safariNotes.id='journalSafari';const safariHeading=document.createElement('summary');safariHeading.id='journalSafariSummary';const safariList=document.createElement('ul');safariList.id='journalSafariList';const safariHint=document.createElement('p');safariHint.id='journalSafariHint';safariNotes.append(safariHeading,safariList,safariHint);dialog.append(title,summary,safariNotes,filters,body,close);document.body.append(dialog);
 const style=document.createElement('link');style.rel='stylesheet';style.href='journal.css';document.head.append(style);const nav=document.createElement('button');nav.id='journalButton';nav.textContent='Keepsake journal';$('nav').append(nav);
 const searchControls=document.createElement('div');searchControls.id='journalSearchControls';const searchLabel=document.createElement('label');searchLabel.htmlFor='journalSearch';searchLabel.textContent='Find a keepsake';const search=document.createElement('input');search.id='journalSearch';search.type='search';search.maxLength=120;search.placeholder='Name, place or theme';search.value='';const clear=button('Clear search','journalSearchClear',()=>{search.value='';render();search.focus();});const searchCount=document.createElement('p');searchCount.id='journalSearchCount';searchCount.setAttribute('role','status');searchCount.setAttribute('aria-live','polite');search.setAttribute('aria-controls','journalItems');searchControls.append(searchLabel,search,clear,searchCount);search.oninput=()=>render();
 const normalize=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
 const hosts=document.createElement('details');hosts.id='journalHosts';const hostsTitle=document.createElement('summary');hostsTitle.id='journalHostsSummary';const hostsList=document.createElement('div');hostsList.id='journalHostsList';hosts.append(hostsTitle,hostsList);dialog.replaceChildren(title,summary,safariNotes,hosts,searchControls,filters,body,close);
 let filter='all';const filterButtons=[];
 function button(text,id,fn){const b=document.createElement('button');b.textContent=text;b.id=id;b.onclick=()=>{if(!dialog.open||b.disabled)return;return fn();};return b;}
 const walk=p=>{rewards.guideToPoint(p);dialog.close();},station=id=>{rewards.guideTo(id);dialog.close();};
 const safariAnimals=[['giraffe','Giraffes'],['elephant','Elephants'],['zebra','Zebras'],['lion','Lions'],['hippo','Hippos'],['flamingo','Flamingos']];
 safariNotes.append(button('Walk to safari boarding','journalSafariGo',()=>walk({x:48,z:-26,name:'Safari boarding'})));
 function renderSafari(){const st=rewards.state(),recorded=id=>st.done.includes('safari-sighting-'+id),count=safariAnimals.filter(([id])=>recorded(id)).length;safariHeading.textContent='Safari sightings · '+count+' / 6';safariList.replaceChildren();for(const [id,name]of safariAnimals){const row=document.createElement('li');row.textContent=name+' · '+(recorded(id)?'Recorded':'Not yet recorded');safariList.append(row);}safariHint.textContent=(count===6?'All six animal groups recorded. Your Safari Field Notebook is available for your home display.':'At each safari habitat stop, open Field guide and choose Record sighting. You can finish over several rides.')+' '+(st.saved?'Saved in this browser and included in progress backups.':'Progress is available for this visit only.');}
 function items(){const st=rewards.state(),earned=new Set(lounges.collection().map(s=>s.id));
  const entries=[
   {id:'founder',name:'Founder’s Crown pin',kind:'Pin',owned:founder(),hint:'Find the crown beside the Discovery Garden pond.',go:()=>walk({x:18,z:-47,name:'Founder’s Crown'})},
   {id:'journey',name:'Great Journey pin',kind:'Pin',owned:st.pins.includes('great-journey'),hint:st.done.includes('great-journey')?'Your ride is complete. Claim its task reward at The Great Journey station.':'Complete all six stops of The Great Journey, then claim its task reward.',go:()=>st.done.includes('great-journey')?station('journey'):walk({x:-32,z:-33,name:'The Great Journey boarding'})},
   {id:'coffee',name:'Lisa’s Coffee Shop pin',kind:'Pin',owned:st.pins.includes('lisas-coffee'),hint:st.done.includes('coffee-order')?'Collect your coffee-shop pin at Lisa’s rewards station.':'Order a virtual drink, then collect the pin at Lisa’s rewards station.',go:()=>st.done.includes('coffee-order')?station('cafe'):walk({x:24,z:-18,name:'Lisa’s coffee counter'})},
   {id:'safari',name:'Safari Explorer pin',kind:'Pin',owned:st.pins.includes('safari-explorer'),hint:st.done.includes('safari-complete')?'Your safari is complete. Claim its task reward at the safari station.':'Visit all six safari habitats and return, then claim the safari task reward.',go:()=>st.done.includes('safari-complete')?station('safari'):walk({x:48,z:-26,name:'Safari boarding'})}
  ];
  entries.push({id:'safari-notebook',name:'Safari Field Notebook',kind:'Safari keepsake',owned:safariAnimals.every(([id])=>st.done.includes('safari-sighting-'+id)),hint:safariAnimals.filter(([id])=>st.done.includes('safari-sighting-'+id)).length+' / 6 animal groups recorded. Record a sighting at each habitat stop to earn your notebook.',display:true,go:()=>walk({x:48,z:-26,name:'Safari boarding'})});
  entries.push({id:'builders-crown',name:'Builder’s Crown',kind:'Garden keepsake',owned:builders.collection().length>0,hint:[0,1,2].filter(i=>st.done.includes('builders-page-'+i)).length+' / 3 chapters explored. Return to the exhibit to continue and collect your crown.',display:true,go:()=>walk({x:-26,z:30,name:'Making of Krownlandia exhibit'})});
  entries.push({id:'alexandria-bookmark',name:'Alexandria Bookmark',kind:'Library keepsake',owned:library.collection().length>0,hint:library.progress().count+' / 3 readings explored. Return to the reading desk to continue and collect your bookmark.',display:true,go:()=>walk(library.deskPoint)});
  entries.push({id:'eldergrove-leaf',name:'Eldergrove Woodcarved Leaf',kind:'Village keepsake',owned:eldergrove.collection().length>0,hint:eldergrove.progress().count+' / 3 forest discoveries recorded. Explore the remaining stops to earn your leaf.',display:true,go:()=>walk(eldergrove.progress().next||eldergrove.points[0])});
  entries.push({id:'school-first-star',name:'First Lesson Star',kind:'Magic School keepsake',owned:st.done.includes('school-pattern'),hint:'Match Gold, Teal and Rose in the Magic School lantern lesson. You can study at the board or sit at either desk.',display:true,go:()=>walk(school.deskPoint)});
  for(const s of lounges.spots)entries.push({id:'lounge-'+s.id,name:s.souvenir,kind:'Lounge souvenir',revisitName:s.name,owned:earned.has(s.id),hint:'Visit '+s.name+' and choose Collect in the lounge menu.',display:true,go:()=>walk({x:s.x,z:s.z+1.3,name:s.name})});
  const next=residents.people.find(p=>!p.met);entries.push({id:'village-welcome',name:'Village Welcome Pennant',kind:'Neighborhood souvenir',owned:residents.progress().complete,hint:'Meet Rowan, Mira, and Fern · '+residents.progress().met.length+' / 3 greeted.',display:true,go:()=>{if(next)walk({x:next.x,z:next.z+1.5,name:next.name+' · Village host'});}});
  const counts={'school-first-star':school.progress().started?1:0,'safari-notebook':safariAnimals.filter(([id])=>st.done.includes('safari-sighting-'+id)).length,'builders-crown':[0,1,2].filter(i=>st.done.includes('builders-page-'+i)).length,'alexandria-bookmark':library.progress().count,'eldergrove-leaf':eldergrove.progress().count,'village-welcome':residents.progress().met.length};
  const ready={journey:st.done.includes('great-journey'),coffee:st.done.includes('coffee-order'),safari:st.done.includes('safari-complete'),'builders-crown':counts['builders-crown']===3,'alexandria-bookmark':counts['alexandria-bookmark']===3};
  for(const item of entries){item.ready=!item.owned&&!!ready[item.id];item.inProgress=!item.owned&&(item.ready||(counts[item.id]||0)>0);if(item.ready&&item.id==='builders-crown')item.hint='All three chapters explored. Return to the exhibit and choose Collect Builder’s Crown.';if(item.ready&&item.id==='alexandria-bookmark')item.hint='All three readings explored. Return to the reading desk and choose Collect Alexandria Bookmark.';}
  return entries;
 }
 function renderHosts(){const progress=residents.progress();hostsTitle.textContent='Village hosts · '+progress.met.length+' / 3 greeted';hostsList.replaceChildren();for(const person of residents.people){const met=progress.met.includes(person.id),row=document.createElement('p');row.textContent=person.name+' · '+({meadow:'Meadow Village',harbor:'Bluewater Village',woodland:'Woodland Village'}[person.id]||'Village')+' · '+(met?'Greeted':'Still to meet');row.append(button(met?'Visit again':'Meet '+person.name,'journalHost-'+person.id,()=>walk({x:person.x,z:person.z+1.5,name:person.name+' · Village host'})));hostsList.append(row);}}
 function render(){renderSafari();renderHosts();const all=items(),count=all.filter(i=>i.owned).length;summary.textContent=count+' / '+all.length+' keepsakes collected · '+all.filter(i=>i.ready).length+' ready to collect';for(const b of filterButtons)b.setAttribute('aria-pressed',String(b.filter===filter));body.replaceChildren();const terms=normalize(search.value).split(' ').filter(Boolean),filtered=all.filter(i=>filter==='all'||(filter==='collected'?i.owned:filter==='progress'?i.inProgress:filter==='ready'?i.ready:!i.owned)),shown=filtered.filter(i=>{const text=normalize([i.id,i.name,i.kind,i.hint].join(' '));return terms.every(term=>text.includes(term));});clear.hidden=!search.value;searchCount.textContent=shown.length+' of '+filtered.length+' keepsakes shown'+(filter==='all'?'':' in this filter');
  if(!shown.length){const p=document.createElement('p');p.textContent=terms.length?'No keepsakes match this search and filter. Clear search or choose All to explore more.':filter==='ready'?'No keepsakes are waiting to be collected. Choose In progress to continue an activity, or Still to find to begin one.':filter==='progress'?'No unfinished discoveries in progress. Choose Still to find to start something new.':filter==='collected'?'Your first keepsake is waiting. Choose Still to find to get directions.':'You have collected every keepsake in the journal!';body.append(p);}
  for(const item of shown){const card=document.createElement('article');card.className='journal-card';card.setAttribute('data-owned',String(item.owned));const heading=document.createElement('h3');heading.textContent=item.name;const state=document.createElement('p');state.className='journal-state';state.textContent=item.kind+' · '+(item.owned?'Collected':item.ready?'Ready to collect':item.inProgress?'In progress':'Still to find');const hint=document.createElement('p');hint.textContent=item.owned?(item.display?'Available for your home’s framed souvenir display.':'Collected in your park pin collection.'):item.hint;card.append(heading,state,hint);
   if(!item.owned)card.append(button(item.ready?'Find collection spot':'Guide me','journalGuide-'+item.id,item.go));else if(item.display)card.append(button('Open home display','journalDisplay-'+item.id,()=>{dialog.close();villages.openDisplay(item.id);}));if(item.owned&&item.revisitName)card.append(button('Revisit '+item.revisitName,'journalRevisit-'+item.id,()=>{if(!dialog.open)return;item.go();}));body.append(card);
  }
 }
 for(const [id,label]of [['all','All'],['collected','Collected'],['missing','Still to find'],['progress','In progress'],['ready','Ready to collect']]){const b=button(label,'journalFilter-'+id,()=>{filter=id;render();});b.filter=id;filterButtons.push(b);filters.append(b);}
 function open(){if(dialog.open){render();return;}pause();safariNotes.open=false;hosts.open=false;render();dialog.showModal();}nav.onclick=open;return {open,items,get isOpen(){return dialog.open}};
}
